/* Constants */
export const HIGHLIGHT_NAMES = ["attribute","comment","constant","constructor","escape","function","keyword","label","module","number","operator","property","punctuation","string","tag","type","variable.builtin","variable.parameter"] as const;

/* Types */
export type Action = {
	action: string,
	closes: string[],
};

export type ActorDto = {
	name: string,
	description: string,
};

/**  How a terminal's agent stands after a hook event. */
export type AgentHookState = "working" | "input" | "done" | "failed" | "idle" | "gone";

/**  The last agent pass: how many changes it made and what it touched. */
export type AgentPass = {
	changed: number,
	/**  Part, shape, group, note and arrow ids, and edges as `from>to`. */
	touched: string[],
	view: string,
};

/**  An agent asked the workspace's review pane to review `revset`. */
export type AgentRevset = {
	workspace: string | null,
	revset: string,
};

/**
 *  An agent asked to see `path` at `line`: in the review pane, or an editor when the review
 *  doesn't change it.
 */
export type AgentShow = {
	workspace: string | null,
	path: string,
	line: number | null,
};

export type Answer = Answer_Serialize | Answer_Deserialize;

/**  An answer to a question: an option from 0, or none of them with `other`. */
export type AnswerInput = {
	option: number | null,
	note: string | null,
	other: string | null,
};

export type Answer_Deserialize = {
	/**  The option picked, from 0. `None` for an answer outside the options. */
	option: number | null,
	note?: string | null,
	/**  The answer in the user's words, when it's none of the options. */
	other?: string | null,
	/**  When it was decided, in ms, so the last decision can be undone. */
	at: number | null,
	/**
	 *  Why the agent answered it itself, with option 1, when it did. Auto answers come with
	 *  the questions, so undo leaves them.
	 */
	auto?: string | null,
};

export type Answer_Serialize = {
	/**  The option picked, from 0. `None` for an answer outside the options. */
	option: number | null,
	note?: string | null,
	/**  The answer in the user's words, when it's none of the options. */
	other?: string | null,
	/**  When it was decided, in ms, so the last decision can be undone. */
	at: number | null,
	/**
	 *  Why the agent answered it itself, with option 1, when it did. Auto answers come with
	 *  the questions, so undo leaves them.
	 */
	auto?: string | null,
};

/**  A terminal agent assessed review `review`'s architecture. */
export type ArchChanged = {
	workspace: string | null,
	review: number,
};

export type ArchDto = {
	containers: ContainerDto[],
	components: ComponentDto[],
	edges: EdgeDto[],
	/**  Assess's layers once it has run, else one per changed component in dependency order. */
	layers: LayerDto[],
	look: LookDto[],
	assessment: AssessmentDto | null,
	counts: CountsDto,
};

/**  Two commits to compare instead of the review's base and head. */
export type ArchRange = {
	/**  Absent for the root. */
	from: string | null,
	to: string,
};

export type ArchViewDto = {
	untracked: boolean,
	tests: boolean,
	generated: boolean,
	/**  Containers with fewer than `SMALL` files. */
	small: boolean,
	/**  People and external systems. */
	outside: boolean,
	groups: boolean,
	labels: EdgeLabels,
	unaffected: Unaffected,
};

/**  An arrow's end: stuck to a part, shape, group or note, or free at `at`. */
export type ArrowEnd = {
	/**  A part, shape, group or note id; none when the end is free. */
	target: string | null,
	/**  Where a free end is, and where an attached one was last drawn. */
	at?: Pt,
};

export type AssessmentDto = {
	/**  1 (risky) to 5 (safe to merge). */
	score: number,
	risk: RiskLevel,
	reason: string,
	boundaries: BoundaryDto[],
	createdAt: number | null,
	/**  Whether the revset has moved to other commits since. */
	stale?: boolean,
};

/**  Where `@` is: in the review, right on top of it, or elsewhere. */
export type AtPlace = "inside" | "onTop" | "outside";

export type Author = "user" | "agent";

export type BehaviorChange = {
	/**  Markdown; empty for new behavior. */
	before?: string,
	/**  Markdown; empty for removed behavior. */
	after?: string,
};

/**  A local bookmark and the change it's on. */
export type BookmarkSpot = {
	name: string,
	/**  The change id, short. */
	change: string,
	/**  Length of the shortest prefix of `change` that's unique in the repo. */
	unique: number,
};

/**  A report on a revset, frozen at the commits it resolved to when it was first published. */
export type BotRun = {
	id: number,
	/**  What the user renamed it to. Its id is `R<id>` until then. */
	name?: string | null,
	workspace: string | null,
	revset: string,
	from: string | null,
	to: string,
	/**
	 *  `from` and `to` are the revset's whole range. False for reports stored before they
	 *  were, which may have an open view's base.
	 */
	whole?: boolean,
	personas: Persona[],
	parts: Part[],
	createdAt: number | null,
	/**  Ids of findings the user dismissed. */
	dismissed?: string[],
};

/**  An agent published findings to report `run`, so the workspace's dock opens it. */
export type BotRunChanged = {
	run: number,
	workspace: string | null,
};

export type BoundaryDto = {
	name: string,
	components: string[],
};

export type Caller = {
	/**  The calling function or other symbol. */
	name: string,
	/**  Workspace-relative path. */
	path: string,
	/**  1-based line of the call. */
	line: number,
};

export type Canvas = {
	/**
	 *  By view: a drawing's is `main`; a design's are `context`, `containers`,
	 *  `components/<container id>` and `interfaces/<component id>`.
	 */
	views?: { [key in string]: ViewCanvas },
	/**  Part colors, by part id, in every view. */
	colors?: { [key in string]: Swatch },
	agent?: AgentPass | null,
};

/**  An arrow, or without a head, a line. */
export type CanvasArrow = {
	id: string,
	from: ArrowEnd,
	to: ArrowEnd,
	color: Swatch | null,
	pattern: LinePattern,
	head?: boolean,
	by?: CanvasAuthor,
};

/**  Who last made or changed an element. */
export type CanvasAuthor = "user" | "agent";

export type CanvasFocus = {
	kind: CanvasKind,
	/**  The drawing's or design's id. */
	id: string,
	view: string,
	/**  Selected element ids. */
	selection: string[],
	/**  A design view's parts; none for a drawing. */
	parts: FocusPart[],
};

/**  A labeled frame around parts, shapes and other groups. */
export type CanvasGroup = {
	id: string,
	label: string,
	color: Swatch | null,
	/**  Part and shape ids, which have a `:` (or are `sys`), and group ids, which don't. */
	members: string[],
	by?: CanvasAuthor,
};

export type CanvasKind = "drawing" | "design";

/**  Text on the canvas: plain, or on a sticky note. */
export type CanvasNote = {
	id: string,
	text: string,
	/**  Its top left. */
	at: Pt,
	size: NoteSize,
	color: Swatch | null,
	sticky?: boolean,
	by?: CanvasAuthor,
};

/**  A box the user or an agent drew, with its text inside. */
export type CanvasShape = {
	/**  Starts with `s:`. */
	id: string,
	kind: ShapeKind,
	/**  Its top left. */
	at: Pt,
	w: number,
	h: number,
	text: string,
	color: Swatch | null,
	/**  Tinted inside, else an outline only. */
	fill: boolean,
	pattern: LinePattern,
	by?: CanvasAuthor,
};

/**
 *  A rewrite of a decided question, which opened it again, or an auto answer the user
 *  reopened, that the user hasn't looked at yet.
 */
export type Change = Change_Serialize | Change_Deserialize;

export type ChangeDto = {
	changeId: string,
	commitId: string,
	/**  Length of the shortest prefix of `change_id` that's unique in the repo. */
	unique: number,
	/**  Whether it's the workspace's working-copy commit. */
	workingCopy: boolean,
	/**  Whether it has unresolved conflicts. */
	conflict: boolean,
	/**  Whether it changes no files. */
	empty: boolean,
	/**  Whether other visible commits share its change id. */
	divergent: boolean,
	/**  Its local bookmarks, each ending in `*` when the remote lacks it or is behind. */
	bookmarks: string[],
	description: string,
	since: Since,
};

/**
 *  A rewrite of a decided question, which opened it again, or an auto answer the user
 *  reopened, that the user hasn't looked at yet.
 */
export type Change_Deserialize = {
	/**
	 *  What it was rewritten after: a question id, "discussion", or "auto" for a reopened
	 *  auto answer.
	 */
	after: string,
	/**  What changed, in a few words. */
	what: string,
	previous: QText_Deserialize,
	/**  The answer it had before it reopened. */
	answer?: Answer_Deserialize | null,
};

/**
 *  A rewrite of a decided question, which opened it again, or an auto answer the user
 *  reopened, that the user hasn't looked at yet.
 */
export type Change_Serialize = {
	/**
	 *  What it was rewritten after: a question id, "discussion", or "auto" for a reopened
	 *  auto answer.
	 */
	after: string,
	/**  What changed, in a few words. */
	what: string,
	previous: QText_Serialize,
	/**  The answer it had before it reopened. */
	answer: Answer_Serialize | null,
};

export type CheckState = "unchecked" | "checked" | 
/**  Was checked, but the file now has changed rows the check didn't cover. */
"changedSinceReviewed";

export type Choice = Choice_Serialize | Choice_Deserialize;

export type Choice_Deserialize = {
	label: string,
	/**  What it means, in a line. */
	means?: string,
	pros?: string[],
	cons?: string[],
	/**  Downsides worse than a con. */
	risks?: string[],
	/**  What it means and what it costs, from sessions before pros and cons. */
	bullets?: string[],
};

export type Choice_Serialize = {
	label: string,
	/**  What it means, in a line. */
	means: string,
	pros: string[],
	cons: string[],
	/**  Downsides worse than a con. */
	risks: string[],
	/**  What it means and what it costs, from sessions before pros and cons. */
	bullets?: string[],
};

export type ChunkDto = {
	/**  Kept across updates of the guided review, so verdicts follow the chunk. */
	id: string,
	title: string,
	risk: ChunkRisk,
	tags: string[],
	summary?: ChunkSummary,
	/**  The changed lines it's made of, in the review's files. */
	ranges: GuidedRange[],
	/**  Unchanged lines read alongside it, in any file. */
	related: GuidedRange[],
	steps: StepDto[],
	/**  Paths of the context docs it bears on. */
	docs: string[],
	tests: TestsDto | null,
	/**  The person made it from excluded code and picked its risk. */
	promoted: boolean,
};

export type ChunkRisk = "high" | "medium" | "low";

export type ChunkSummary = {
	/**
	 *  Markdown: why a new function, command, type or system exists. Empty for a change to
	 *  existing code that needs no why.
	 */
	purpose?: string,
	/**  The questions a reviewer would ask first, each with a short answer. */
	context?: Qa[],
	/**  The choices behind this implementation, a line of markdown each. */
	decisions?: string[],
	/**  What users or callers see differently. */
	behavior?: BehaviorChange[],
	/**  New, changed or removed signatures, commands, flags, MCP tools, schemas or config. */
	interface?: InterfaceChange[],
	/**  Effects on stored or persisted data: migrations, formats, state; a line of markdown each. */
	data?: string[],
};

export type ChunkVerdict = "approved" | 
/**  Sent back to the agent with a note. */
"change" | "skipped";

/**  How the `claudeTerminal` setting resolved, for the Settings tab. */
export type ClaudeCommand = {
	setting: string,
	/**  The command line that runs, like `ucode claude` for the alias `cc`. */
	resolved: string | null,
	/**  It's a shell function, so each run goes through the login shell. */
	viaShell: boolean,
	error: string | null,
};

export type CodeSymbol = {
	name: string,
	kind: SymbolKind,
	/**  1-based, inclusive. Includes leading decorators, attributes, and doc comments. */
	startLine: number,
	endLine: number,
	/**  The parse has errors inside the range, so the range can't be trusted. */
	hasError: boolean,
};

export type CommentDto = {
	id: number,
	path: string,
	/**  The review file it belongs to. */
	file: number,
	/**  Absent when its code can't be found any more. */
	rows: RowSpan | null,
	body: string,
	/**  The code as it was when the comment was made. */
	snippet: string,
	review: string,
	createdAt: number | null,
	updatedAt: number | null,
	messages: Message[],
	/**  A reply a synced terminal agent suggested. */
	suggestion: string | null,
	/**  The GitHub thread it's on, whose replies show above it. */
	github: GhLink | null,
	/**  Set on GitHub threads and drafts of them; notes have none. */
	thread: ThreadState | null,
	/**  A note the user is done with. */
	done: boolean,
};

export type CompStatus = 
/**  Only at head. */
"added" | 
/**  Only at base. */
"removed" | 
/**  Has a changed file. */
"changed" | 
/**  Unchanged, but a changed component uses it. */
"upstream" | 
/**  Unchanged, but uses a changed or removed symbol of a changed component. */
"impacted" | "unchanged";

export type ComponentDescDto = {
	id: string,
	description: string,
	tier: string | null,
};

export type ComponentDto = {
	/**  The folder (or root, for loose files) it was grouped from. */
	id: string,
	/**  The folder's name. */
	name: string,
	container: string,
	/**  Files at head, plus removed files. */
	files: FileRefDto[],
	status: CompStatus,
	/**  The first layer that covers it, 1-based. */
	layer: number | null,
	/**  The worst open Look item on it. */
	severity: LookSeverity | null,
};

export type ContainerDescDto = {
	id: string,
	name: string,
	tech: string,
	description: string,
};

/**  A source root, like a crate's `src/` or a package root. */
export type ContainerDto = {
	/**  The root's repo-relative path, "" for the repo root. */
	id: string,
	name: string,
};

